import{_ as i,a0 as a,w as s,s as p,I as t,x as o,a1 as r,A as n,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用Clonezilla對硬盤進行鏡像和克隆 | LCTT x X-CMD","titleTemplate":false,"description":"使用Clonezilla對硬盤進行鏡像和克隆 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用Clonezilla對硬盤進行鏡像和克隆 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用Clonezilla對硬盤進行鏡像和克隆 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140811 How to Image and Clone Hard Drives with Clonezilla","title":"使用Clonezilla對硬盤進行鏡像和克隆","tag":"201409","desc":""},"relativePath":"201409/20140811 How to Image and Clone Hard Drives with Clonezilla.md","filePath":"[post].md"}'),d={name:"201409/20140811 How to Image and Clone Hard Drives with Clonezilla.md"};function C(m,l,z,w,g,f){const e=a("Link");return s(),p("div",null,[l[27]||(l[27]=t("h1",{id:"使用clonezilla對硬盤進行鏡像和克隆",tabindex:"-1"},[o("使用Clonezilla對硬盤進行鏡像和克隆 "),t("a",{class:"header-anchor",href:"#使用clonezilla對硬盤進行鏡像和克隆","aria-label":"Permalink to “使用Clonezilla對硬盤進行鏡像和克隆”"},"​")],-1)),l[28]||(l[28]=t("p",null,"Clonezilla是一個用於Linux，Free-Net-OpenBSD，Mac OS X，Windows以及Minix的分區和磁盤克隆程序。它支持所有主要的文件系統，包括EXT，NTFS，FAT，XFS，JFS和Btrfs，LVM2，以及VMWare的企業集羣文件系統VMFS3和VMFS5。Clonezilla支持32位和64位系統，同時支持舊版BIOS和UEFI BIOS，並且同時支持MBR和GPT分區表。它是一個用於完整備份Windows系統和所有安裝於上的應用軟件的好工具，而我喜歡用它來為Linux測試系統做備份，以便我可以在其上做瘋狂的實驗搞壞後，可以快速恢復它們。",-1)),l[29]||(l[29]=t("p",null,"Clonezilla也可以使用dd命令來備份不支持的文件系統，該命令可以複製塊而非文件，因而不必在意文件系統。簡單點説，就是Clonezilla可以複製任何東西。（關於塊的快速説明：磁盤扇區是磁盤上最小的可編址存儲單元，而塊是由單個或者多個扇區組成的邏輯數據結構。）",-1)),l[30]||(l[30]=t("p",null,"Clonezilla分為兩個版本：Clonezilla Live和Clonezilla Server Edition（SE）。Clonezilla Live對於將單個計算機克隆到本地存儲設備或者網絡共享來説是一流的。而Clonezilla SE則適合更大的部署，用於一次性快速多點克隆整個網絡中的PC。Clonezilla SE是一個神奇的軟件，我們將在今後討論。今天，我們將創建一個Clonezilla Live USB存儲棒，克隆某個系統，然後恢復它。",-1)),l[31]||(l[31]=t("h3",{id:"clonezilla和tuxboot",tabindex:"-1"},[o("Clonezilla和Tuxboot "),t("a",{class:"header-anchor",href:"#clonezilla和tuxboot","aria-label":"Permalink to “Clonezilla和Tuxboot”"},"​")],-1)),t("p",null,[l[1]||(l[1]=o("當你訪問下載頁時，你會看到",-1)),r(e,{href:"http://www.linux.com/learn/tutorials/783416-how-to-image-and-clone-hard-drives-with-clonezilla#57_why_ubuntu_based_clonezilla_live.faq"},{default:n(()=>[...l[0]||(l[0]=[o("穩定版和可選穩定發行版",-1)])]),_:1}),l[2]||(l[2]=o("。也有測試版本，如果你有興趣幫助改善Clonezilla，那麼我推薦你使用此版本。穩定版基於Debian，不含有非自由軟件。可選穩定版基於Ubuntu，包含有一些非自由固件，並支持UEFI安全啓動。",-1))]),t("p",null,[l[5]||(l[5]=o("在你",-1)),r(e,{href:"http://clonezilla.org/downloads.php"},{default:n(()=>[...l[3]||(l[3]=[o("下載Clonezilla",-1)])]),_:1}),l[6]||(l[6]=o("後，請安裝",-1)),r(e,{href:"http://tuxboot.sourceforge.net/"},{default:n(()=>[...l[4]||(l[4]=[o("Tuxboot",-1)])]),_:1}),l[7]||(l[7]=o("來複制Clonezilla到USB存儲棒。Tuxboot是一個Unetbootin的修改版，它支持Clonezilla；你不能使用Unetbootin，因為它無法配合工作。安裝Tuxboot有點讓人頭痛，然而Ubuntu用户通過個人包歸檔包（PPA）方便地安裝：",-1))]),l[32]||(l[32]=t("pre",null,[t("code",null,`$ sudo apt-add-repository ppa:thomas.tsai/ubuntu-tuxboot
$ sudo apt-get update
$ sudo apt-get install tuxboot
`)],-1)),t("p",null,[l[9]||(l[9]=o("如果你沒有運行Ubuntu，並且你的發行版不包含打包好的Tuxboot版本，那麼請",-1)),r(e,{href:"http://sourceforge.net/projects/tuxboot/files/"},{default:n(()=>[...l[8]||(l[8]=[o("下載源代碼tarball",-1)])]),_:1}),l[10]||(l[10]=o("，並遵循README.txt文件中的説明來編譯並安裝。",-1))]),l[33]||(l[33]=u(`<p><img src="http://www.linux.com/images/stories/41373/fig-1-gparted.jpeg" alt="Figure 1: Creating a partition on the USB stick for Clonezilla."></p><p><em>圖1： 在USB存儲棒上為Clonezilla創建分區</em></p><p>安裝完Tuxboot後，就可以使用它來創建你精巧的可直接啓動的Clonezilla USB存儲棒了。首先，創建一個最小200MB的FAT 32分區；圖1（上圖）展示了使用GParted來進行分區。我喜歡使用類似“Clonezilla”這樣的標籤，這會讓我知道它是個什麼東西。該例子中展示了將一個2GB的存儲棒格式化成一個單個分區。</p><p>然後，啓動Tuxboot（圖2）。選中“預下載的（Pre-downloaded）”然後點擊帶省略號的按鈕來選擇Clonezilla文件。它會自動發現你的USB存儲棒，而你需要選中分區號來確保它找到的是正確的那個，我的例子中是/dev/sdd1。點擊確定，然後當它完成後點擊退出。它會問你是否要重啓動，不要擔心，現在不用重啓。現在你有一個精巧的便攜式Clonezilla USB存儲棒了，你可以隨時隨地使用它了。</p><p><img src="http://www.linux.com/images/stories/41373/fig-2-tuxboot.jpeg" alt="Figure 2: Fire up Tuxboot."></p><p><em>圖2： 啓動Tuxboot</em></p><h3 id="創建磁盤鏡像" tabindex="-1">創建磁盤鏡像 <a class="header-anchor" href="#創建磁盤鏡像" aria-label="Permalink to “創建磁盤鏡像”">​</a></h3><p>在你想要備份的計算機上啓動Clonezilla USB存儲棒，第一個映入你眼簾的是常規的啓動菜單。啓動到默認條目。你會被問及使用何種語言和鍵盤，而當你到達啓動Clonezilla菜單時，請選擇啓動Clonezilla。在下一級菜單中選擇設備鏡像，然後進入下一屏。</p><p>這一屏有點讓人摸不着頭腦，裏頭有什麼local_dev，ssh_server，samba_server，以及nfs_server之類的選項。這裏就是要你選擇將備份的鏡像拷貝到哪裏，目標分區或者驅動器必須和你要拷貝的卷要一樣大，甚至更大。如果你選擇local_dev，那麼你需要一個足夠大的本地分區來存儲你的鏡像。附加的USB硬盤驅動器是一個不錯的，快速而又簡單的選項。如果你選擇任何服務器選項，你需要能連接到服務器，並提供IP地址並登錄上去。我將使用一個本地分區，這就是説要選擇local_dev。</p><p>當你選擇local_dev時，Clonezilla會掃描所有連接到本地的存儲折本，包括硬盤和USB存儲設備。然後，它會列出所有分區。選擇你想要存儲鏡像的分區，然後它會問你使用哪個目錄並列出目錄。選擇你所需要的目錄，然後進入下一屏，它會顯示所有的掛載以及已使用/可用的空間。按回車進入下一屏，請選擇初學者還是專家模式。我選擇初學者模式。</p><p>在下一屏中，你可以選擇存盤，就是選擇創建整個硬盤的鏡像，還是創建分區鏡像，創建分區鏡像允許你選擇單個分區。我想要選擇分區。</p><p>下一屏中，它會問你新建鏡像的名稱。在接受默認名稱，或者輸入你自己的名稱後，進入下一屏。Clonezilla會掃描你所有的分區並創建一個檢查列表，你可以從中選擇你想要拷貝的。選擇完後，在下一屏中會讓你選擇是否進行文件系統檢查並修復。我才沒這耐心，所以直接跳過了。</p><p>下一屏中，會問你是否想要Clonezilla檢查你新創建的鏡像，以確保它是可恢復的。選“是”吧，確保萬無一失。接下來，它會給你一個命令列提示，如果你想用命令列而非GUI，那麼你必須再次按回車。你需要再次確認，並輸入y來確認製作拷貝。</p><p>在Clonezilla創建新鏡像的時候，你可以好好欣賞一下這個友好的紅、白、藍三色的進度屏（圖3）。</p><p><img src="http://www.linux.com/images/stories/41373/fig-3-export.jpeg" alt="Figure 3: Watch the creation of your new image."></p><p><em>圖3： 守候創建新鏡像</em></p><p>全部完成後，按回車然後選擇重啓，記得拔下你的Clonezilla USB存儲棒。正常啓動計算機，然後去看看你新創建的Clonezilla鏡像吧。你應該看到像下面這樣的東西：</p><pre><code>$ ls -l /2014-08-07-11-img/
total 1241448
-rw-r--r-- 1 root root       1223 Aug  7 04:22 blkdev.list
-rw-r--r-- 1 root root        636 Aug  7 04:22 blkid.list
-rw-r--r-- 1 root root       3658 Aug  7 04:24 clonezilla-img
-rw-r--r-- 1 root root      12379 Aug  7 04:24 Info-dmi.txt
-rw-r--r-- 1 root root      22685 Aug  7 04:24 Info-lshw.txt
-rw-r--r-- 1 root root       3652 Aug  7 04:24 Info-lspci.txt
-rw-r--r-- 1 root root        171 Aug  7 04:24 Info-packages.txt
-rw-r--r-- 1 root root         86 Aug  7 04:24 Info-saved-by-cmd.txt
-rw-r--r-- 1 root root          5 Aug  7 04:24 parts
-rw------- 1 root root 1270096769 Aug  7 04:24 sda6.ext4-ptcl-img.gz.aa
-rw-r--r-- 1 root root         37 Aug  7 04:22 sda-chs.sf
-rw-r--r-- 1 root root    1048064 Aug  7 04:22 sda-hidden-data-after-mbr
-rw-r--r-- 1 root root        512 Aug  7 04:22 sda-mbr
-rw-r--r-- 1 root root        750 Aug  7 04:22 sda-pt.parted
-rw-r--r-- 1 root root        625 Aug  7 04:22 sda-pt.parted.compact
-rw-r--r-- 1 root root        514 Aug  7 04:22 sda-pt.sf
</code></pre><h3 id="恢復clonezilla鏡像" tabindex="-1">恢復Clonezilla鏡像 <a class="header-anchor" href="#恢復clonezilla鏡像" aria-label="Permalink to “恢復Clonezilla鏡像”">​</a></h3><p>恢復鏡像和創建鏡像類似。再次使用Clonezilla啓動，經過同樣的初始化步驟後，選擇dev_image，然後在local_dev屏，選擇你要恢復的鏡像所在的位置，它要麼在本地設備上，要麼在網絡共享上。然後繼續下面的操作，確保你的恢復鏡像正確，並選擇了正確的位置。</p>`,20)),t("p",null,[l[12]||(l[12]=o("你可以在",-1)),r(e,{href:"http://clonezilla.org/clonezilla-live-doc.php"},{default:n(()=>[...l[11]||(l[11]=[o("Clonezilla Live文檔頁",-1)])]),_:1}),l[13]||(l[13]=o("獲得更多Clonezilla的神奇力量。",-1))]),l[34]||(l[34]=t("hr",null,null,-1)),t("p",null,[l[15]||(l[15]=o("via: ",-1)),r(e,{href:"http://www.linux.com/learn/tutorials/783416-how-to-image-and-clone-hard-drives-with-clonezilla"},{default:n(()=>[...l[14]||(l[14]=[o("http://www.linux.com/learn/tutorials/783416-how-to-image-and-clone-hard-drives-with-clonezilla",-1)])]),_:1})]),t("p",null,[l[19]||(l[19]=o("作者：",-1)),r(e,{href:"http://www.linux.com/community/forums/person/3734"},{default:n(()=>[...l[16]||(l[16]=[o("Carla Schroder",-1)])]),_:1}),l[20]||(l[20]=o(" 譯者：",-1)),r(e,{href:"https://github.com/GOLinux"},{default:n(()=>[...l[17]||(l[17]=[o("GOLinux",-1)])]),_:1}),l[21]||(l[21]=o(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:n(()=>[...l[18]||(l[18]=[o("wxy",-1)])]),_:1})]),t("p",null,[l[24]||(l[24]=o("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[22]||(l[22]=[o("LCTT",-1)])]),_:1}),l[25]||(l[25]=o(" 原創翻譯，",-1)),r(e,{href:"http://linux.cn/"},{default:n(()=>[...l[23]||(l[23]=[o("Linux中國",-1)])]),_:1}),l[26]||(l[26]=o(" 榮譽推出",-1))])])}const v=i(d,[["render",C]]);export{T as __pageData,v as default};
